"""Vietnamese review of the 95 German lexemes added/changed by the 2026-10-28 re-author.
Writes lexicon-review records (glossVi, exampleTranslationsVi for the kept examples,
dropExamples, addExamples). usage: python -I de-review-new.py <out.jsonl>"""
import json, sys

R = []
def rec(id_, gloss, vi, drop=None, add=None):
    r = {"id": id_, "glossVi": gloss, "exampleTranslationsVi": vi}
    if drop: r["dropExamples"] = drop
    if add: r["addExamples"] = [{"target": t, "en": e, "vi": v} for t, e, v in add]
    R.append(r)

